import itertools

def lis_len(p):
    import bisect
    d=[]
    for x in p:
        i=bisect.bisect_left(d,x)
        if i==len(d): d.append(x)
        else: d[i]=x
    return len(d)

def lds_len(p):
    import bisect
    d=[]
    for x in p:
        x=-x
        i=bisect.bisect_left(d,x)
        if i==len(d): d.append(x)
        else: d[i]=x
    return len(d)

cnt=0
examples=[]
for p in itertools.permutations(range(1,9)):
    if lis_len(p)<=3 and lds_len(p)<=3:
        cnt+=1
        if len(examples)<5: examples.append(p)
print(cnt)
print(examples)
